import math

state = {'step': 0, 'views_seen': {}}

def to_xy(origin, bearing_deg, dist_m):
    b = math.radians(bearing_deg)
    return (round(origin[0] + dist_m * math.cos(b), 2), round(origin[1] + dist_m * math.sin(b), 2))

def control(obs):
    hitch = obs['hitch_deg']
    steer = max(-42.0, min(42.0, 2.5 * hitch))
    speed = -1.2

    views = obs.get('views', {})
    for k in ['camera', 'right_mirror', 'left_mirror', 'direct']:
        if k in views and k not in state['views_seen']:
            v = views[k]
            pts = [to_xy(v['origin'], w[0], w[1]) for w in v.get('walls', [])]
            state['views_seen'][k] = pts
            print(f"{k}: {pts}")
            if v.get('target_corners'):
                print(f"{k}_target: {[to_xy(v['origin'], w[0], w[1]) for w in v['target_corners']]}")

    if 'camera' not in state['views_seen']:
        look = -41.0
    elif 'right_mirror' not in state['views_seen']:
        look = -72.0
    elif 'left_mirror' not in state['views_seen']:
        look = 53.0
    else:
        look = -41.0
        if state['step'] == 0:
            state['step'] = 1
            wake('scanned all views')

    return (steer, speed, look)

