import math

state = {'last_log': 0.0}

def to_xy(origin, bearing_deg, dist_m):
    b = math.radians(bearing_deg)
    return (round(origin[0] + dist_m * math.cos(b), 2), round(origin[1] + dist_m * math.sin(b), 2))

def control(obs):
    hitch = obs['hitch_deg']
    cov = obs['progress']['covered']

    # Slight left bias (+3 deg hitch) for the first 6m to position slightly towards outside of right L-turn, then straighten
    target_hitch = 3.0 if cov < 5.0 else 0.0
    err = hitch - target_hitch
    steer = max(-42.0, min(42.0, 2.5 * err + 0.3 * obs['steer_deg']))
    speed = -2.0
    look = -41.0

    views = obs.get('views', {})
    if 'camera' in views and cov - state['last_log'] >= 2.0:
        state['last_log'] = cov
        v = views['camera']
        pts = [to_xy(v['origin'], w[0], w[1]) for w in v.get('walls', [])]
        print(f"cov={cov:.1f} hitch={hitch:.1f} cam={pts}")

    if cov >= 8.5:
        wake(f"reached cov={cov:.1f}")

    return (steer, speed, look)

