    cov = obs['progress']['covered']

    if cov < 12.0:
        target_hitch = -8.0
    elif cov < 16.0:
        target_hitch = -16.0
    else:
        target_hitch = -26.0

    err = hitch - target_hitch
    # Feedforward steer for holding a hitch angle while reversing: roughly -1.1 * target_hitch
    ff = -1.1 * hitch
    steer = max(-42.0, min(42.0, ff + 2.8 * err))
    speed = -1.8
    look = -41.0

    views = obs.get('views', {})
    if 'camera' in views and cov - state['last_log'] >= 2.0:
        state['last_log'] = cov
        v = views['camera']
        pts = [to_xy(v['origin'], w[0], w[1]) for w in v.get('walls', [])]
        print(f"cov={cov:.1f} hitch={hitch:.1f} steer={obs['steer_deg']:.1f} cam={pts}")

    if cov >= 20.0:
        wake(f"reached cov={cov:.1f}")

    return (steer, speed, look)

